(5, 'ledger', 'Ledger', 'Adds a \'Watch This\' feature on each market that alerts you about any bids/listings/sales; allows bulk market transactions; allows gold transfers; shows monthly sales figures with tallied profits & losses; shows stats on Machines page.', 1),
(6, 'calculator', 'Calculator', 'Shows user stats.  Covers things, findings, vehicles and weapons.', 1),
(7, 'sharpener', 'Whetting Stone', 'Vehicles: Adds 10% to weapon offensive power.<BR>\nShips: Each shot has +10% chance of doing double damage.<BR>\nAircraft: 40% higher bomb damage.<BR>Gadget must be active before sending.', 0),
(8, 'shield', 'Shield', 'Vehicles: Adds 10% to weapon defensive power.<BR>\nShips: Adds 10% to hull.<BR>  \nAircraft: 40% lower chance of being shot down.<BR>Gadget must be active before sending.', 0),
(9, 'turbo', 'Turbo Engine', 'Adds 5km/hr to the speed of vehicles, ships and aircraft.  Search Planes are 10% faster on missions.  <BR>Gadget must be active before sending.', 0),
(10, 'radar', 'Radar', 'Send screen shows the number of traders, highwaymen, guards, merchants, pirates, bounty hunters, fishermen and pilots on each route excluding your own.  Air routes show numbers per aircraft type.', 0),
(11, 'spreadsheet', 'Spreadsheet', 'Shows where a listing in one city is lower than a bid in another city, sorted by the most profitable trades.  Shows foreign bids on item pages.  Enables sending from vehicles/ships/aircraft tabs.', 1),
(12, 'medal_detector', 'Meldal Detector', 'Shows prices of obtaining remaining items for each meld on the Mines page.  Also features a meld shopping list which shows the 10 cheapest melds according to listing prices.  Both features account for equipment.', 1),
(13, 'binoculars', 'Binoculars', 'Reveals the type and owner of each vehicle or ship encountered en route.<BR>Gadget must be active before sending.', 0),
(14, 'control', 'Remote Control', 'Allows the use of a 4th mine at 25 bph.  You must already own a 4th mine to make use of this gadget.  The mine cannot use MRs or equipment and does not benefit from the home city bonus.', 0);

