--
-- Table structure for table `items`
--

CREATE TABLE `items` (
  `id` int(10) UNSIGNED NOT NULL,
  `name` varchar(100) NOT NULL,
  `rarity` smallint(5) UNSIGNED NOT NULL DEFAULT '1',
  `description` mediumtext NOT NULL,
  `marketable_id` int(10) UNSIGNED DEFAULT NULL,
  `mine_type_id` mediumint(8) UNSIGNED NOT NULL DEFAULT '1',
  `sort_priority` smallint(5) UNSIGNED DEFAULT NULL,
  `number_owned` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `discoverer_id` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `discovery_date` datetime DEFAULT NULL,
  `needs_image` tinyint(1) NOT NULL DEFAULT '1',
  `repaired_item_id` int(10) UNSIGNED DEFAULT NULL,
  `can_find` tinyint(3) UNSIGNED NOT NULL DEFAULT '1',
  `use_label` varchar(10) DEFAULT NULL,
  `use_rrl` varchar(50) DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

