(1073, 'Red Dwarf', 4, 'Far better than any mining robot, dwarves have mining in their blood.  A dwarf in your inventory will work at the city\'s mines finding things for you.  Red Dwarves compete with each other to have the largest collection of things.  They occasionally hold competitions to see who can give them the biggest pile of trash and reward the winner with a flood of green+ findings.  Capture one stowing away on a vehicle/ship and you can make him mine for you (until he escapes)! ', NULL, 23, NULL, 730, 156710, '2016-05-23 10:43:46', 1, NULL, 1, NULL, NULL),
