(1294, 'Oil', 0, 'Oil is pumped from the ground using machines and packaged at pads into barrels.  159L makes 1 barrel of oil.  Oil has several uses:<BR> - When loaded onto vehicles/ships, adds 5 km/hr to speed.  <BR> - When given to a factory worker, adds 1 cph until the contract expires.  <BR> - When given to yourself as a worker, adds 1 cph until you change profession. <BR> - When given to a bot, adds 10 bph for 5 days. ', 1193, 25, NULL, 29262, 120265, '2016-06-12 06:03:52', 1, NULL, 1, NULL, NULL),
