--
-- Table structure for table `items_miners`
--

CREATE TABLE `items_miners` (
  `id` int(10) UNSIGNED NOT NULL,
  `miner_id` int(10) UNSIGNED NOT NULL,
  `item_id` int(10) UNSIGNED NOT NULL,
  `city_id` int(10) UNSIGNED DEFAULT NULL,
  `container_miners_vehicle_id` int(10) UNSIGNED DEFAULT NULL,
  `can_sell` tinyint(1) NOT NULL DEFAULT '1',
  `created` datetime NOT NULL,
  `modified` datetime NOT NULL COMMENT 'Used for "Latest Listings"'
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Table structure for table `land2_battle_stats`
--

CREATE TABLE `land2_battle_stats` (
  `id` int(10) UNSIGNED NOT NULL,
  `battle_stat_id` int(10) UNSIGNED NOT NULL,
  `starting_attack` decimal(4,1) UNSIGNED NOT NULL,
  `starting_armor` decimal(4,1) UNSIGNED NOT NULL,
  `starting_offense` decimal(4,1) UNSIGNED NOT NULL,
  `starting_defense` decimal(4,1) UNSIGNED NOT NULL,
  `starting_dodge` smallint(5) UNSIGNED NOT NULL,
  `ending_attack` decimal(4,1) UNSIGNED NOT NULL,
  `ending_armor` decimal(4,1) UNSIGNED NOT NULL,
  `rounds` smallint(5) UNSIGNED NOT NULL,
  `final_blow` decimal(4,1) UNSIGNED NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

