  `offense` float UNSIGNED NOT NULL,
  `defense` float UNSIGNED NOT NULL,
  `meld_boost` smallint(5) UNSIGNED NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

