--
-- Table structure for table `marketable_watches`
--

CREATE TABLE `marketable_watches` (
  `id` int(10) UNSIGNED NOT NULL,
  `marketable_id` int(10) UNSIGNED DEFAULT NULL,
  `miner_id` int(10) UNSIGNED NOT NULL,
  `city_id` int(10) UNSIGNED DEFAULT NULL,
  `created` datetime NOT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

-- --------------------------------------------------------

--
-- Table structure for table `melds`
--

CREATE TABLE `melds` (
  `id` int(10) UNSIGNED NOT NULL,
  `name` varchar(100) NOT NULL,
  `mine_type_id` int(10) UNSIGNED NOT NULL,
  `modified` datetime NOT NULL COMMENT 'used to track the time somebody discovered it',
  `rarity` int(10) UNSIGNED NOT NULL,
  `public` tinyint(1) NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

