--
-- Table structure for table `miners`
--

CREATE TABLE `miners` (
  `id` int(10) UNSIGNED NOT NULL,
  `name` varchar(100) NOT NULL,
  `email` varchar(320) DEFAULT NULL,
  `password` varchar(50) NOT NULL,
  `currency` varchar(6) NOT NULL DEFAULT 'USD',
  `meld_count` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `stone_count` smallint(5) UNSIGNED NOT NULL DEFAULT '0',
  `unread_message_count` smallint(5) UNSIGNED NOT NULL DEFAULT '0',
  `banking_inbox_count` mediumint(8) UNSIGNED NOT NULL DEFAULT '0',
  `gold` decimal(13,4) NOT NULL DEFAULT '0.0000',
  `gold_rate` float NOT NULL DEFAULT '0',
  `gold_updated` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `credits` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `authority` smallint(6) NOT NULL DEFAULT '0',
  `home_city_id` int(10) UNSIGNED NOT NULL DEFAULT '1',
  `current_city_id` int(10) UNSIGNED NOT NULL DEFAULT '1',
  `last_moved` datetime DEFAULT NULL,
  `previous_home_city_id` smallint(5) UNSIGNED DEFAULT NULL,
  `profession` mediumint(9) NOT NULL DEFAULT '0',
  `item_count` int(10) UNSIGNED NOT NULL DEFAULT '0',
  `item_limit` int(10) UNSIGNED NOT NULL,
  `battery_expire_time` int(11) DEFAULT NULL,
  `converted` tinyint(3) UNSIGNED NOT NULL DEFAULT '0',
  `retained` tinyint(1) UNSIGNED NOT NULL DEFAULT '0',
  `purchased` tinyint(4) NOT NULL DEFAULT '0',
  `tutorial_stage_id` mediumint(8) UNSIGNED DEFAULT '1',
  `publish_findings` tinyint(3) UNSIGNED NOT NULL DEFAULT '1',
  `show_mines` tinyint(3) UNSIGNED NOT NULL DEFAULT '1',
  `actions` smallint(5) UNSIGNED NOT NULL DEFAULT '0',
  `created` datetime NOT NULL DEFAULT '2011-01-01 00:00:00'
) ENGINE=MyISAM DEFAULT CHARSET=latin1;

