--
-- Dumping data for table `tutorial_stages`
--

INSERT INTO `tutorial_stages` (`id`, `name`, `title`, `instructions`, `trigger_url`) VALUES
(1, 'Find Something', 'Mine a Thing', 'This is the Minethings tutorial.  It will guide you through the basics of the game and show you around the menu.  \r\nYou have been given a tutorial mine to start with.  To see what you\'ve found in this mine, click \"Findings\" (below on the left).', '/mines/check_mines'),
(7, 'Buy Flimsy', 'Buy Equipment', 'Now you have some gold and you can see your gold count above has increased.  Gold is used in all market transactions between players.  You can buy anything in the game if you have enough gold.\r\nOn your Findings page, you see a miner bot with grayed out spots where equipment should be.  Equipment is useful because it allows you to mine faster than the default rate.  Click on the bot and you\'ll be taken to the equipment mine page.  Then click on \"Tutorial Drill\" (colored yellow), click \"Buy,\" then \"Buy for 8g.\"', ''),
(8, 'Findings', 'Bought Equipment', 'You just bought the Tutorial Drill.   \r\nHave a look at your new drill by clicking \"Findings\" (below on the left).', '/mines/check_mines'),
(2, 'Find both Yellows', 'Find Apple and Orange', 'You have now found your first thing.  On this page you can see your miner bot mining at your Tutorial mine.  Your bot is always working and will find things continuously regardless of what you do.  Because this is the Tutorial mine, you are finding things at an enormous rate.  By clicking Findings, you get to see what it has found most recently.\r\nWait a bit and then click \"Findings\" again.  Continue until you have found both an apple and an orange.', ''),
(3, 'Make Meld', 'Make a Fruit Meld', 'Your level in the game is determined by now many melds you have.  A meld is a collection of things that you have either found or bought with gold.\r\nNow that you have an apple and an orange, you can use both to make the Fruit meld.  \r\nTo create this meld, click \"Tutorial mine\" (to the right of the miner bot), then \"Fruit\" (in the Melds section), then press the \"Create Meld\" button.', ''),
(4, 'Find Green', 'Find a Carrot', 'You now have the Fruit meld.  Notice that the number next to your name above has increased to 1.  You\'ll also notice that the button you just clicked is gone.  This is because each meld can only be created once.  \r\nCheck on your Findings and see if you found a Carrot.  This is a green item, which is quite a bit rarer than a yellow item.  If you haven\'t found one yet, wait a bit and check again by clicking \"Findings.\"', ''),
(5, 'Sell Green', 'Sell your Carrot', 'You have now found a Carrot.  It can be used in a meld but let\'s look at how you can sell this one.  Since Carrots are green and rarer than yellows, they tend to fetch a higher price. \r\nTo sell your Carrot, click \"Carrot\" (in your Findings list), then \"Sell,\" then \"Sell for 15g.\"', ''),
(6, 'Find Gold', 'Sold Carrot', 'Good, you just sold your carrot.  \r\nThe other way to make gold is to find it from your mine.  Click Findings, then \"mine gold.\"  Wait a bit and then check your Findings again.  Continue until you have found gold twice.  The tutorial mine delivers findings at an enormous rate, so this won\'t take long.', ''),
(9, 'Things', 'New Drill', 'You can see here that your miner bot is using the new drill and you are mining at 31 buckets per hour instead of 30.  \r\nTake a look again at the things you own by clicking \"Things\" (below on the left).  ', '/miners/things'),
(10, 'Gadgets', 'Things', 'The Things page shows you all the things you own in Rackham.  There are other cities where you can store things, but for now you only have access to Rackham and all of your things are here.  This page also shows you which melds you have.\nClick on \"Gadgets\" (below on the left).  ', '/gadgets'),
(11, 'Factories', 'Gadgets', 'Here is where you would use gadgets you have bought or found.  Gadgets are temporary boosts that you can buy from other players using gold.  There are many types providing benefits like faster vehicles, more attack power, stronger ship hulls, and more inventory.  \r\nNow click \"Factories\" (below on the left).', '/factories'),
(12, 'Profession', 'Factories', 'Factories are primarily used to create advanced models of mining robots.  Factories are built and operated using ore and workers.  One of the easiest ways for you to make extra gold in this game is to work at another player\'s factory (requires 10 melds).  \r\nNow click \"Profession\" (below on the left).', '/miners/profession'),
(13, 'Messages', 'Profession', 'This page shows the many professions that you can be in Minethings.  They are unlocked as you earn melds.  Professions allow you to use vehicles, ships and factories in different ways.\r\nNow click \"Home\" (brown menu).', '/'),
(14, 'Miners', 'Home Page', 'There\'s a lot to see on the home page.  \"Discoveries\" shows you the last 10 things that were discovered and who discovered them.  \"Listings\" shows the last 10 market listings in Rackham.  \"Bids\" shows the last 10 bids.  The middle column contains any ads that people might have placed to promote their listings or bids.  \nNow click \"Miners\" (brown menu).', '/miners/list_miners'),
(15, 'Mines', 'Miners', 'The Miners page shows you who else is playing the game.  The list starts with the miners who have achieved the most melds and continues from there.  You can browse the list or use the search box to find other miners.\r\nNow click \"Mines\" (brown menu).', '/mine_types/browse'),
(16, 'Bugs', 'Mines', 'The Mines page shows you all the things available in the game organized by the mine in which they are found.  All of the things seen on this page are available for purchase from other players once the tutorial is finished.\r\nHave a look at the Spices mine by clicking \"Spices\" (below).', '/mine_types/browse/6'),
(17, 'Shop', 'Spice Mine', 'The Spices mine page shows the 36 things available from the Spices mine organized by rarity.  The most common items are colored yellow and the rarest ones are colored orange.  \r\nNow click \"Shop\" (brown menu).', '/credits/shop'),
(18, 'Starter Market', 'Shop', 'While you\'ll start the game with just one mine, you can work at up to three mines at once.  The shop is where you can purchase these additional mines.  The Rackham shop shows you the mines available in Rackham and there are many more available in other cities.  You can buy a mine using either credits or gold.  \nHave a look at the Starter mine market by clicking \"Starter Mine Market\" (below).', '/marketables/market/792'),
(19, 'Facebook', 'Starter Mine Market', 'Here you can buy an additional Starter mine from another player using gold instead of credits.  You might not have this much gold for a while but there are many ways to earn gold in this game.  There are also gold loans available from other players.\r\nNow click \"Facebook\" (brown menu).', '/facebook/index'),
(20, 'Help', 'Facebook', 'The Facebook page give you an opportunity to share Minethings with your friends and earn credits at the same time.  Everything you need to begin can be found here.  \r\nNow click \"Help\" (brown menu).', '/miners/help'),
(21, 'Refresh Batteries', 'Help', 'This tutorial does not cover everything you can do in this game so the help page is here for when you want to learn more about other features.  \r\nNow that you\'ve seen the menu, notice that you have a battery timer above.  If that runs out, your bot will stop mining.  Click \"Findings\" (below on the left) now to recharge your battery.', '/mines/check_mines'),
(22, 'Exit', 'Tutorial Finished', 'You have been given a very brief overview of the game and now know enough to get started.  There is a lot to explore further including professions, forums, and the map.  \r\nBe aware that all other mines find things at a much slower rate than the Tutorial mine and it can be a long wait between findings.  Equipment will help speed things up.  You do not have to be logged in to mine -- you are mining 24/7 as long as your battery is fresh.\r\nYou will now get a starter mine and have your gold, melds and things reset.  Enjoy the game!', '*'),
(36, 'Exit', 'Tutorial Finished', 'You have been given a very brief overview of the game and now know enough to get started.  There is a lot to explore further including professions, forums, and the map.\r\nBe aware that all other mines find things at a much slower rate than the Tutorial mine and it can be a long wait between findings.  Equipment will help speed things up.  You do not have to be logged in to mine -- you are mining 24/7 as long as your battery is fresh.\r\nYou will now get a starter mine and have your gold, melds and things reset.  Enjoy the game!', '*'),
(35, 'Messages', 'Profession', 'This page shows the many professions that you can be in Minethings. They are unlocked as you earn melds. Professions allow you to use vehicles, ships and factories in different ways.\r\nNow that you\'ve seen the menu, notice that you have a battery timer above. If that runs out, your bot will stop mining. Click \"Findings\" (below on the left) now to recharge your battery.', '/mines/check_mines'),
(33, 'Factories', 'Gadgets', 'Here is where you would use gadgets you have bought or found.  Gadgets are temporary boosts that you can buy from other players using gold.  There are many types providing benefits like faster vehicles, more attack power, stronger ship hulls, and more inventory.  \r\nNow click \"Factories\" (below on the left).', '/factories'),
(34, 'Profession', 'Factories', 'Factories are primarily used to create advanced models of mining robots.  Factories are built and operated using ore and workers.  One of the easiest ways for you to make extra gold in this game is to work at another player\'s factory (requires 10 melds).\r\nNow click \"Profession\" (below on the left).', '/miners/profession'),
(31, 'Things', 'New Drill', 'You can see here that your miner bot is using the new drill and you are mining at 26 buckets per hour instead of 25.\r\nTake a look again at the things you own by clicking \"Things\" (below on the left).  ', '/miners/things'),
(32, 'Gadgets', 'Things', 'The Things page shows you all the things you own in Rackham.  There are other cities where you can store things, but for now you only have access to Rackham and all of your things are here.  This page also shows you which melds you have.\nClick on \"Gadgets\" (below on the left).  ', '/gadgets'),
(30, 'Findings', 'Bought Equipment', 'You just bought the Tutorial Drill.\r\nHave a look at your new drill by clicking \"Findings\" (below on the left).', '/mines/check_mines'),
(29, 'Buy Flimsy', 'Buy Equipment', 'Now you have some gold and you can see your gold count above has increased.  Gold is used in all market transactions between players.  You can buy anything in the game if you have enough gold.\r\nOn your Findings page, you see a miner bot with grayed out spots where equipment should be.  Equipment is useful because it allows you to mine faster than the default rate.  Click on the bot and you\'ll be taken to the equipment mine page.  Then click on \"Tutorial Drill\" (colored yellow), click \"Buy,\" then \"Buy for 8g.\"', ''),
(28, 'Sell Green', 'Sell your Carrot', 'You have now found a Carrot.  It can be used in a meld but let\'s look at how you can sell this one.  Since Carrots are green and rarer than yellows, they tend to fetch a higher price.\r\nTo sell your Carrot, click \"Carrot\" (in your Findings list), then \"Sell,\" then \"Sell for 15g.\"', ''),
(24, 'Find Something', 'Mine a Thing', 'This is the Minethings tutorial.  It will guide you through the basics of the game and show you around the menu.\r\nYou have been given a tutorial mine to start with.  To see what you\'ve found in this mine, click \"Findings\" (below on the left).', '/mines/check_mines'),
(25, 'Find both Yellows', 'Find Apple and Orange', 'You have now found your first thing.  On this page you can see your miner bot mining at your Tutorial mine.  Your bot is always working and will find things continuously regardless of what you do.  Because this is the Tutorial mine, you are finding things at an enormous rate.  By clicking Findings, you get to see what it has found most recently.\r\nWait a bit and then click \"Findings\" again.  Continue until you have found both an apple and an orange.', ''),
(26, 'Make Meld', 'Make a Fruit Meld', 'Your level in the game is determined by now many melds you have.  A meld is a collection of things that you have either found or bought with gold.\r\nNow that you have an apple and an orange, you can use both to make the Fruit meld.\r\nTo create this meld, click \"Tutorial mine\" (to the right of the miner bot), then \"Fruit\" (in the Melds section), then press the \"Create Meld\" button.', ''),
(27, 'Find Green', 'Find a Carrot', 'You now have the Fruit meld.  Notice that the number next to your name above has increased to 1.  You\'ll also notice that the button you just clicked is gone.  This is because each meld can only be created once.\r\nCheck on your Findings and see if you found a Carrot.  This is a green item, which is quite a bit rarer than a yellow item.  If you haven\'t found one yet, wait a bit and check again by clicking \"Findings.\"', '');

